window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[65]={"id":"065","numero":65,"titre":"Trouble délirant persistant","objectifs":[{"id":"65-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des idées délirantes","contenu":"<p>Une <span class=\"kw-def\">idée délirante</span> est une <strong>altération du contenu de la pensée</strong> : une <span class=\"kw-def\">conviction erronée</span>, en désaccord avec la réalité, <strong>inébranlable</strong> et <span class=\"kw-alerte\">inaccessible au raisonnement et à la critique</span>.</p>\n      <p>Une idée délirante se caractérise par plusieurs <span class=\"kw-def\">dimensions sémiologiques</span> : son <strong>thème</strong>, son ou ses <strong>mécanisme(s)</strong>, sa <strong>systématisation</strong> et le degré d'<strong>adhésion</strong> du patient (l'analyse détaillée de ces axes fait l'objet de l'objectif « analyse sémiologique d'un syndrome délirant »).</p>\n      <p>Il existe <strong>4 mécanismes</strong> à l'origine d'une idée délirante :</p>\n      <ul>\n        <li>Mécanisme <span class=\"kw-def\">interprétatif</span></li>\n        <li>Mécanisme <span class=\"kw-def\">intuitif</span></li>\n        <li>Mécanisme <span class=\"kw-def\">imaginatif</span></li>\n        <li>Mécanisme <span class=\"kw-def\">hallucinatoire</span></li>\n      </ul>\n      <div class=\"callout callout-info\">📌 L'<span class=\"kw-def\">adhésion</span> est le degré de conviction attaché aux idées délirantes. Elle est <strong>partielle</strong> si le patient est en mesure de critiquer ses idées délirantes, <strong>totale</strong> lorsque la conviction est inébranlable et inaccessible au raisonnement et à la critique.</div>","frequence":0},{"id":"65-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition du trouble délirant persistant","contenu":"<p>Le <span class=\"kw-def\">trouble délirant persistant</span> est un <span class=\"kw-def\">trouble psychotique chronique</span> dit « <strong>non schizophrénique</strong> ». Il se définit par la présence d'<strong>une ou plusieurs idées délirantes persistantes</strong>, en l'absence des marqueurs de la <span class=\"kw-etio\">schizophrénie</span>.</p>\n      <p>Caractéristiques du syndrome délirant dans le trouble délirant persistant :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Thème</span> généralement <strong>unique</strong> — la <strong>persécution</strong> est le plus fréquent.</li>\n        <li><span class=\"kw-def\">Mécanismes</span> : interprétatif, intuitif, imaginatif.</li>\n        <li>Délire <strong>systématisé</strong> (organisé, doté d'une logique interne).</li>\n        <li><span class=\"kw-clinique\">Adhésion totale</span>.</li>\n      </ul>\n      <p>Arguments cliniques distinguant le trouble délirant persistant de la <span class=\"kw-etio\">schizophrénie</span> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Hallucinations</span> pas au 1<sup>er</sup> plan.</li>\n        <li><span class=\"kw-alerte\">Absence de dissociation / désorganisation</span>.</li>\n        <li>Pas de <span class=\"kw-alerte\">syndrome négatif</span>.</li>\n        <li><strong>Jamais d'<span class=\"kw-clinique\">évolution</span> déficitaire</strong>.</li>\n      </ul>\n      <div class=\"callout callout-info\">📌 <span class=\"kw-clinique\">Les</span> deux grands troubles psychotiques chroniques partagent une <strong>perte durable du <span class=\"kw-def\">contact</span> avec la réalité</strong> et un syndrome délirant chronique, mais s'opposent : la <span class=\"kw-def\">psychose dissociative</span> (<span class=\"kw-etio\">schizophrénie</span>) associe une pensée floue, désorganisée et sans logique ; la <span class=\"kw-def\">psychose non dissociative</span> (trouble délirant persistant) garde une pensée <strong>logique mais organisée autour d'un thème délirant</strong>, sans dissociation.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique</em></p>","frequence":0},{"id":"65-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les facteurs de risque, le pronostic et l’évolution","contenu":"<p>Le trouble délirant persistant est un trouble <strong>rare</strong>, dont l'<span class=\"kw-def\">épidémiologie</span> contraste nettement avec celle de la <span class=\"kw-etio\">schizophrénie</span> — comparaison utile à connaître :</p>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Trouble délirant persistant</th><th><span class=\"kw-etio\">Schizophrénie</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Prévalence</span></td><td><span class=\"kw-chiffre\">0,2 %</span></td><td><span class=\"kw-chiffre\">0,6-1 %</span></td></tr>\n          <tr><td><span class=\"kw-def\">Incidence</span></td><td><span class=\"kw-chiffre\">1-3 / 100 000 / an</span></td><td><span class=\"kw-chiffre\">15 / 100 000 / an</span></td></tr>\n          <tr><td>Sex-ratio</td><td>Proche de <span class=\"kw-chiffre\">1</span></td><td><span class=\"kw-chiffre\">1,4 H / 1 F</span></td></tr>\n          <tr><td>Âge de début</td><td>Âge adulte, le plus souvent <span class=\"kw-chiffre\">40-50 ans</span></td><td>Tout âge, surtout <span class=\"kw-chiffre\">18-25 ans</span></td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-etio\">Facteurs de risque</span> du trouble délirant persistant :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Âge avancé</span></li>\n        <li><span class=\"kw-etio\">Isolement</span>, <span class=\"kw-etio\">immigration</span>, <span class=\"kw-def\">isolement</span> social</li>\n        <li><span class=\"kw-etio\">Antécédents familiaux</span> de troubles délirants</li>\n        <li><span class=\"kw-etio\">Déficits sensoriels</span></li>\n        <li><span class=\"kw-etio\">Troubles de la personnalité</span></li>\n      </ul>\n      <div class=\"callout callout-info\">📌 <strong><span class=\"kw-clinique\">Évolution</span>.</strong> Le trouble est <strong>chronique</strong>. À la différence de la <span class=\"kw-etio\">schizophrénie</span> — où une <span class=\"kw-alerte\">évolution déficitaire</span> est possible (avec stabilisation vers <span class=\"kw-chiffre\">2-5 ans</span>) — le trouble délirant persistant ne comporte <strong>jamais d'évolution déficitaire</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique</em></p>","frequence":0},{"id":"65-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir faire l’analyse sémiologique d’un syndrome délirant","contenu":"<p>L'<span class=\"kw-def\">analyse sémiologique d'un syndrome délirant</span> repose sur la caractérisation systématique de l'idée délirante selon <strong>5 dimensions</strong>. Cette grille oriente le diagnostic entre <span class=\"kw-etio\">schizophrénie</span> et trouble délirant persistant.</p>\n      <table >\n        <thead><tr><th>Dimension</th><th>Définition</th><th><span class=\"kw-etio\">Schizophrénie</span></th><th>Trouble délirant persistant</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Thèmes</span></td><td>Sujet sur lequel porte l'idée délirante ; uniques ou multiples</td><td><strong>Multiples</strong>, hétérogènes : persécution, mégalomanie, somatique, mystique, de référence</td><td>Thème généralement <strong>unique</strong> ; 5 plus fréquents : persécution ++, mégalomanie, somatique, érotomanie, jalousie</td></tr>\n          <tr><td><span class=\"kw-def\">Mécanismes</span></td><td>Processus par lequel l'idée délirante se construit (interprétatif, intuitif, imaginatif, hallucinatoire)</td><td>Mécanismes généralement <strong>nombreux</strong></td><td>Interprétatif ; intuitif ; imaginatif</td></tr>\n          <tr><td><span class=\"kw-def\">Systématisation</span></td><td>Organisation et cohérence des idées délirantes</td><td>Majoritairement <strong>non systématisé</strong> : organisation floue, vague, incohérente</td><td>Majoritairement <strong>systématisé</strong> : il existe une logique interne</td></tr>\n          <tr><td><span class=\"kw-def\">Adhésion</span></td><td>Degré de conviction : partielle (critique possible) ou totale (conviction inébranlable)</td><td>Variable (souvent forte au début, moindre par la suite)</td><td><strong>Totale</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Retentissement</span></td><td>Conséquences émotionnelles et comportementales — à évaluer systématiquement</td><td>À évaluer systématiquement</td><td>À évaluer systématiquement</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ Le <span class=\"kw-alerte\">retentissement</span> doit être évalué systématiquement : niveau d'<span class=\"kw-alerte\">anxiété</span> (souvent majeur), <span class=\"kw-alerte\">risque suicidaire</span>, risque de <span class=\"kw-alerte\">passage à l'acte hétéroagressif</span>. La <strong>dangerosité</strong> pour soi-même ou pour autrui peut être la conséquence directe des idées délirantes (expier ses fautes, se venger d'un « persécuteur »).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique</em></p>","frequence":0},{"id":"65-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques DSM-5","contenu":"<p>Le <span class=\"kw-def\">diagnostic positif</span> du trouble délirant persistant repose sur <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères DSM-5</span>, articulés en 5 critères <strong>A à E</strong> :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>A</strong></td><td>Présence d'<strong>une ou plusieurs idées délirantes</strong> évoluant pendant <span class=\"kw-chiffre\">≥ 1 mois</span></td></tr>\n          <tr><td><strong>B</strong></td><td><span class=\"kw-clinique\">Les</span> idées délirantes <strong>n'apparaissent pas comme bizarres</strong> (contenu relativement <span class=\"kw-clinique\">plausible</span>) ; <span class=\"kw-alerte\">absence de syndrome de désorganisation</span> et de <span class=\"kw-alerte\">syndrome négatif</span> ; si des <span class=\"kw-clinique\">hallucinations</span> sont présentes, elles ne sont pas au 1<sup>er</sup> plan et restent en rapport avec le thème délirant</td></tr>\n          <tr><td><strong>C</strong></td><td>En dehors de l'impact des idées délirantes, <strong>pas d'altération marquée du fonctionnement</strong> ni de bizarrerie manifeste du comportement</td></tr>\n          <tr><td><strong>D</strong></td><td><span class=\"kw-clinique\">Les</span> idées délirantes ne sont <strong>pas associées à des symptômes maniaques ou dépressifs</strong> ; si de tels symptômes existent, ils doivent être <span class=\"kw-clinique\">brefs</span> au regard de la durée des idées délirantes</td></tr>\n          <tr><td><strong>E</strong></td><td><span class=\"kw-clinique\">Les</span> idées délirantes ne sont <strong>pas attribuables</strong> à une pathologie non psychiatrique ni à l'usage d'une <span class=\"kw-ttt\">substance psychoactive</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 <span class=\"kw-clinique\">Les</span> critères <strong>B, C et D</strong> sont des critères d'<strong>exclusion</strong> : ils écartent respectivement la <span class=\"kw-etio\">schizophrénie</span> (désorganisation, syndrome négatif), une altération globale du fonctionnement, et un trouble de l'humeur délirant.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble dépressif</em></p>","frequence":0},{"id":"65-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les formes cliniques","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">formes cliniques</span> du trouble délirant persistant se déclinent <strong>selon le thème</strong> de l'idée délirante :</p>\n      <table >\n        <thead><tr><th>Forme</th><th>Description</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Érotomaniaque</span></td><td>Conviction erronée d'être <strong>aimé(e)</strong> par un individu, le plus souvent de niveau social plus élevé</td><td>Mécanisme <strong>intuitif</strong> au départ puis <strong>interprétatif</strong> ; plus fréquent chez la <span class=\"kw-clinique\">femme</span> ; <span class=\"kw-clinique\">évolution</span> classique en 3 phases — <strong>espoir → dépit → rancune</strong> (phase de rancune : sollicitations devenant injures et menaces, <span class=\"kw-alerte\">risque de passage à l'acte</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Mégalomaniaque</span></td><td>Conviction d'un <strong>talent ou pouvoir méconnu</strong>, d'une découverte importante, de relations haut placées ou d'être soi-même une personnalité importante</td><td>—</td></tr>\n          <tr><td><span class=\"kw-def\">Jalousie</span></td><td>Conviction que le partenaire est <strong>infidèle</strong></td><td>Plus fréquente chez l'<span class=\"kw-clinique\">homme</span> ; <span class=\"kw-etio\">trouble d'usage de l'alcool</span> fréquemment associé</td></tr>\n          <tr><td><span class=\"kw-def\">Persécution</span></td><td>Conviction d'être victime d'un <strong>complot</strong>, d'un espionnage, de tentatives d'empoisonnement ou d'une conspiration</td><td>Fréquemment associée à des <span class=\"kw-clinique\">recours en justice</span> ; <span class=\"kw-alerte\">passages à l'acte violents</span> possibles sur la personne désignée comme « persécuteur »</td></tr>\n          <tr><td><span class=\"kw-def\">Somatique</span></td><td>Idées centrées sur <span class=\"kw-clinique\">les</span> <strong>sensations ou les fonctions corporelles</strong></td><td>Le plus souvent : émettre une <span class=\"kw-clinique\">odeur nauséabonde</span>, être <span class=\"kw-clinique\">infesté d'insectes ou de parasites</span>, parties du corps difformes, organes qui ne fonctionnent pas</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">📌 Deux formes ne correspondent pas à un thème unique : <span class=\"kw-clinique\">les</span> formes <strong>mixtes</strong> (association de plusieurs thèmes sans qu'aucun ne prédomine) et les formes <strong>indifférenciées</strong> (ne correspondant à aucun des sous-types décrits).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 15 — Soins psychiatriques sans consentement · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span></em></p>","frequence":0},{"id":"65-7","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels psychiatriques et non psychiatriques","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">diagnostics différentiels</span> du trouble délirant persistant se répartissent en causes <strong>non psychiatriques</strong>, <strong>toxiques</strong> et <strong>psychiatriques</strong> :</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Diagnostics différentiels</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Non psychiatriques</span></td><td><span class=\"kw-etio\">Troubles neurodégénératifs</span></td></tr>\n          <tr><td><span class=\"kw-def\">Intoxication par une substance psychoactive</span></td><td><span class=\"kw-ttt\">Cannabis</span> ; traitements par <span class=\"kw-ttt\">L-Dopa</span> ou autres <span class=\"kw-ttt\">agonistes dopaminergiques</span></td></tr>\n          <tr><td><span class=\"kw-def\">Psychiatriques</span></td><td><strong>Autres troubles psychotiques :</strong> <span class=\"kw-etio\">schizophrénie</span> ; <span class=\"kw-etio\">troubles schizo-affectifs</span><br><strong>Troubles de l'humeur :</strong> <span class=\"kw-etio\">manie délirante</span> ; <span class=\"kw-etio\">mélancolie délirante</span><br><strong>Troubles de la personnalité :</strong> <span class=\"kw-etio\">paranoïaque</span> ; <span class=\"kw-etio\">borderline</span> ; <span class=\"kw-etio\">antisociale</span><br><strong>Dans certains cas :</strong> <span class=\"kw-etio\">troubles obsessionnels-compulsifs</span></td></tr>\n        </tbody>\n      </table>\n      <p>Un <span class=\"kw-def\">bilan paraclinique</span> est réalisé afin d'éliminer une cause non psychiatrique :</p>\n      <ul>\n        <li><strong>Biologie :</strong> <span class=\"kw-bio\">glycémie</span> ; <span class=\"kw-bio\">NFS</span> ; <span class=\"kw-bio\">ionogramme</span> ; <span class=\"kw-bio\">urée</span> ; <span class=\"kw-bio\">créatinine</span> ; <span class=\"kw-bio\">bilan hépatique</span> ; <span class=\"kw-bio\">calcémie</span> ; <span class=\"kw-bio\">TSH</span></li>\n        <li><strong>Toxiques :</strong> <span class=\"kw-bio\">toxiques urinaires</span></li>\n        <li><strong><span class=\"kw-bio\">ECG</span></strong></li>\n        <li><strong>Imagerie cérébrale :</strong> selon la clinique et le contexte</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble dépressif &amp; de la personnalité · 77 — Addiction aux psychotropes</em></p>","frequence":0},{"id":"65-8","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge","contenu":"<p>La prise en charge du trouble délirant persistant articule une réflexion sur le <strong>lieu de soins</strong>, un <strong>traitement pharmacologique</strong> et un <strong>traitement non pharmacologique</strong>.</p>\n      <div class=\"callout callout-danger\">⚠️ <strong><span class=\"kw-alerte\">Hospitalisation</span> en psychiatrie.</strong> L'hospitalisation pose de nombreux problèmes thérapeutiques : elle <span class=\"kw-alerte\">accentue souvent le sentiment de persécution</span> et peut <span class=\"kw-alerte\">aggraver les comportements de revendication</span> fondés sur <span class=\"kw-clinique\">les</span> idées délirantes. Si des soins sans consentement sont indiqués, la modalité <span class=\"kw-clinique\">SPDRE</span> peut être utilisée — notamment lorsque l'entourage familial et social correspond au « persécuteur désigné » et qu'il existe un risque pour la sûreté des personnes.</div>\n      <table >\n        <thead><tr><th>Volet</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Traitement pharmacologique</span></td><td><strong><span class=\"kw-ttt\">Antipsychotique</span> :</strong> <span class=\"kw-ttt\">recommandé</span> dans le trouble délirant persistant, d'efficacité <strong>modérée</strong><br><strong><span class=\"kw-ttt\">Antidépresseur</span> :</strong> associé, parfois nécessaire en cas d'<span class=\"kw-clinique\">épisode dépressif caractérisé</span> ou de <span class=\"kw-clinique\">troubles anxieux</span> associés</td></tr>\n          <tr><td><span class=\"kw-def\">Traitement non pharmacologique</span></td><td><span class=\"kw-clinique\">Psychothérapie</span> de soutien ou cognitivo-comportementale, à proposer <strong>systématiquement</strong> en association au traitement <span class=\"kw-etio\">médicamenteux</span> ; la thérapie <strong>individuelle</strong> semble plus efficace que la thérapie de groupe</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 15 — Soins psychiatriques sans consentement · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span></em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> trouble <span class=\"kw-def\">psychotique chronique</span>, sans <span class=\"kw-alerte\">urgence</span> diagnostique propre.<br><strong>Urgence réelle :</strong> le <span class=\"kw-alerte\">risque suicidaire</span> et le <span class=\"kw-alerte\">passage à l'acte hétéroagressif</span> sont à évaluer systématiquement à chaque consultation.<br><strong>1er geste :</strong> si passage à l'acte imminent, mise en sécurité du patient et des tiers puis recours aux <span class=\"kw-ttt\">soins psychiatriques sans consentement</span> (SPDRE).</p>","hospit":"<p><strong>Par défaut :</strong> prise en charge le plus souvent <span class=\"kw-ttt\">ambulatoire</span> ; l'<span class=\"kw-alerte\">hospitalisation</span> <span class=\"kw-alerte\">accentue le sentiment de persécution</span> et peut <span class=\"kw-alerte\">aggraver les comportements de revendication</span>.<br><strong>Soins sans consentement :</strong> modalité <span class=\"kw-ttt\">SPDRE</span> indiquée notamment si l'entourage familial ou social correspond au « <span class=\"kw-etio\">persécuteur désigné</span> » et qu'il existe un risque pour la sûreté des personnes.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Risque suicidaire</span> à rechercher systématiquement (retentissement émotionnel souvent majeur).</li><li><span class=\"kw-alerte\">Passage à l'acte hétéroagressif</span> sur la personne désignée comme « <span class=\"kw-etio\">persécuteur</span> ».</li><li>Forme <span class=\"kw-etio\">érotomaniaque</span> en <strong>phase de rancune</strong> : sollicitations devenues <span class=\"kw-alerte\">injures et menaces</span>.</li><li>Forme à thème de <span class=\"kw-etio\">jalousie</span> avec <span class=\"kw-etio\">trouble d'usage de l'alcool</span> fréquemment associé.</li><li><span class=\"kw-clinique\">Anxiété</span> souvent majeure liée à l'adhésion délirante <span class=\"kw-alerte\">totale</span>.</li><li>Forme de <span class=\"kw-etio\">persécution</span> : recours en justice répétés et dangerosité pour autrui.</li></ul>","principes":"<p>Association systématique d'un <span class=\"kw-ttt\">traitement pharmacologique</span> et d'une <span class=\"kw-ttt\">psychothérapie</span>, après un bilan d'élimination, le plus souvent en ambulatoire.</p><p><strong>Bilan paraclinique d'élimination</strong></p><p>Élimine une cause non psychiatrique (<span class=\"kw-etio\">trouble neurodégénératif</span>) ou <span class=\"kw-etio\">toxique</span> (<span class=\"kw-etio\">cannabis</span>, <span class=\"kw-ttt\">L-Dopa</span>, <span class=\"kw-ttt\">agonistes dopaminergiques</span>) avant de retenir le diagnostic.</p><ul><li><span class=\"kw-bio\">Glycémie</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">TSH</span>, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">urée</span>/<span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">bilan hépatique</span>.</li><li><span class=\"kw-bio\">Toxiques urinaires</span> et <span class=\"kw-bio\">ECG</span>.</li><li><span class=\"kw-imagerie\">Imagerie cérébrale</span> selon la clinique et le contexte.</li></ul><p><strong>Traitement pharmacologique</strong></p><ul><li><span class=\"kw-ttt\">Antipsychotique</span> recommandé en 1re intention, d'efficacité <span class=\"kw-chiffre\">modérée</span>.</li><li><span class=\"kw-ttt\">Antidépresseur</span> associé si <span class=\"kw-etio\">épisode dépressif caractérisé</span> ou <span class=\"kw-etio\">troubles anxieux</span> associés.</li></ul><p><strong>Traitement non pharmacologique</strong></p><ul><li><span class=\"kw-ttt\">Psychothérapie de soutien</span> ou <span class=\"kw-ttt\">cognitivo-comportementale</span> systématiquement proposée, en association au médicament.</li><li>Thérapie <strong>individuelle</strong> plus efficace que la thérapie de groupe.</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Réévaluation</span> :</strong> <span class=\"kw-alerte\">dangerosité</span> auto- et hétéroagressive (<span class=\"kw-alerte\">risque suicidaire</span>, passage à l'acte) à évaluer systématiquement.<br><strong>Traitement :</strong> surveiller la réponse à l'<span class=\"kw-ttt\">antipsychotique</span> (efficacité <span class=\"kw-chiffre\">modérée</span>) et l'observance.<br><strong>Psychothérapie :</strong> poursuite au long cours de la <span class=\"kw-ttt\">psychothérapie de soutien</span> et de l'alliance thérapeutique.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Syndrome délirant chronique évoquant un trouble délirant persistant — Idées délirantes ≥ 1 mois, thème unique, délire systématisé","detail":"<h4>CAT — Trouble délirant persistant — Démarche diagnostique et orientation thérapeutique</h4>","branches":[{"to":"q-organique","label":"1. Éliminer l'organique et le toxique","color":"blue"}]},{"id":"q-organique","kind":"decision","label":"Cause non psychiatrique ou toxique éliminée par le bilan ? — Trouble neurodégénératif, substance psychoactive","branches":[{"to":"t-bilan","label":"Non / bilan non réalisé","color":"amber"},{"to":"q-criteres","label":"Oui","color":"green"}]},{"id":"t-bilan","kind":"terminal","label":"Compléter le bilan paraclinique d'élimination","color":"blue","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Glycémie</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">TSH</span>, <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">urée</span>/<span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">bilan hépatique</span>.</li><li><span class=\"kw-bio\">Toxiques urinaires</span> et <span class=\"kw-bio\">ECG</span>.</li><li><span class=\"kw-imagerie\">Imagerie cérébrale</span> selon la clinique et le contexte.</li></ul><h4>Conduite</h4><ul><li>Éliminer un <span class=\"kw-etio\">trouble neurodégénératif</span> ou une intoxication (<span class=\"kw-etio\">cannabis</span>, <span class=\"kw-ttt\">L-Dopa</span> / <span class=\"kw-ttt\">agonistes dopaminergiques</span>).</li></ul>"},{"id":"q-criteres","kind":"decision","label":"Critères DSM-5 du trouble délirant persistant réunis ? — Pas de désorganisation ni de syndrome négatif, pas de symptômes thymiques au 1er plan","branches":[{"to":"t-diff","label":"Non (désorganisation, syndrome négatif, thèmes multiples)","color":"amber"},{"to":"q-danger","label":"Oui (≥ 1 mois, délire non bizarre systématisé)","color":"blue"}]},{"id":"t-diff","kind":"terminal","label":"Réorienter vers un diagnostic différentiel psychiatrique — Critères non remplis","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-etio\">Schizophrénie</span> / trouble <span class=\"kw-etio\">schizo-affectif</span> : dissociation, syndrome négatif, thèmes multiples.</li><li><span class=\"kw-etio\">Trouble de l'humeur</span> délirant (manie ou mélancolie délirante).</li><li><span class=\"kw-etio\">Trouble de la personnalité</span> (paranoïaque, borderline, antisociale) ou <span class=\"kw-etio\">TOC</span>.</li></ul>"},{"id":"q-danger","kind":"decision","label":"Risque suicidaire ou passage à l'acte hétéroagressif ? — Entourage = persécuteur désigné, érotomanie en phase de rancune","branches":[{"to":"t-ssc","label":"Oui","color":"red"},{"to":"t-ambu","label":"Non","color":"green"}]},{"id":"t-ssc","kind":"terminal","label":"Soins psychiatriques sans consentement (SPDRE) — Risque pour la sûreté des personnes","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">SPDRE</span> notamment si l'entourage est le « <span class=\"kw-etio\">persécuteur désigné</span> ».</li><li><span class=\"kw-alerte\">Mise en sécurité</span> du patient et des tiers.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antipsychotique</span> ± <span class=\"kw-ttt\">antidépresseur</span> si <span class=\"kw-def\">comorbidité</span> thymique ou anxieuse.</li><li><span class=\"kw-ttt\">Psychothérapie</span> introduite dès que possible.</li></ul>"},{"id":"t-ambu","kind":"terminal","label":"Prise en charge ambulatoire — Trouble délirant persistant confirmé, sans dangerosité","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antipsychotique</span> (efficacité <span class=\"kw-chiffre\">modérée</span>) en 1re intention.</li><li><span class=\"kw-ttt\">Psychothérapie</span> de soutien ou <span class=\"kw-ttt\">cognitivo-comportementale</span> systématique, plutôt <strong>individuelle</strong>.</li><li><span class=\"kw-ttt\">Antidépresseur</span> si <span class=\"kw-etio\">épisode dépressif</span> ou anxiété associés.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Réévaluation</span> systématique de la <span class=\"kw-alerte\">dangerosité</span> auto- et hétéroagressive.</li></ul>"}]},"cards":[]};